Custom Exceptions & Error ADTs:
// Error ADT
sealed trait AppError
case class NotFound(id: Int) extends AppError
case class ValidationError(field: String, msg: String) extends AppError
case class DbError(cause: Throwable) extends AppError

type Result[A] = Either[AppError, A]

def findUser(id: Int): Result[String] =
  if (id <= 0) Left(ValidationError("id", "must be positive"))
  else if (id == 42) Left(NotFound(id))
  else Right(s"User $id")

findUser(42) match {
  case Right(user) => println(user)
  case Left(NotFound(id)) => println(s"User $id not found")
  case Left(ValidationError(f, m)) => println(s"$f: $m")
  case Left(DbError(cause)) => throw cause
}

