For-Comprehension Deep:
case class Logged[A](value: A, logs: List[String]) {
  def map[B](f: A => B): Logged[B] =
    Logged(f(value), logs)
  def flatMap[B](f: A => Logged[B]): Logged[B] = {
    val result = f(value)
    Logged(result.value, logs ++ result.logs)
  }
}

object Logged {
  def apply[A](value: A): Logged[A] = Logged(value, Nil)
}

