Future Combinators:
import scala.concurrent.{Future, ExecutionContext}
import ExecutionContext.Implicits.global

val f1 = Future { Thread.sleep(100); 1 }
val f2 = Future { Thread.sleep(200); 2 }
val f3 = Future { Thread.sleep(150); 3 }

// Zip — pair
val zipped: Future[(Int, Int)] = f1 zip f2

// Sequence — all results
val all: Future[List[Int]] = Future.sequence(List(f1, f2, f3))

// Traverse
def asyncId(n: Int) = Future(n)
val traversed: Future[List[Int]] = Future.traverse(1 to 10)(asyncId)

// Race
val first: Future[Int] = Future.firstCompletedOf(List(f1, f2, f3))

